/**
 * T009c corroboration probe. Read-only. Loopback only.
 *
 * It does exactly two things per lane, and neither of them is part of the
 * published measurement: it re-runs the same bounded crawl the witness runner
 * derived its journey from, so the record can name WHICH routes the crawl
 * declared; and it loads the served root in the same Chromium the witness
 * launched, so the record can say what the shell surface actually is when an
 * EJS-templated index.html is served without the Express backend that renders
 * it. Nothing here is stubbed and nothing here is written into a lane.
 */
import { startStaticServer } from '../../../../packages/cli/src/witness/real-app-run.ts';
import { crawlLaneJourneys, CRAWL_DEFAULT_BOUNDS } from '../../../../packages/cli/src/witness/journey-synthesis/crawl.ts';
import { witnessChromiumExecutablePath } from '../../../../packages/cli/src/witness/browser.ts';
import { chromium } from 'playwright';

const lanes = {
  baseline: process.argv[2],
  migrated: process.argv[3],
};
const out = {};
for (const [lane, root] of Object.entries(lanes)) {
  const server = await startStaticServer(root, { profile: 'current-witness' });
  const reading = await crawlLaneJourneys(server.origin, CRAWL_DEFAULT_BOUNDS, fetch);
  const browser = await chromium.launch({ executablePath: witnessChromiumExecutablePath(), headless: true });
  const page = await browser.newPage();
  const consoleErrors = [];
  const failedRequests = [];
  page.on('console', (m) => { if (m.type() === 'error') consoleErrors.push(m.text().slice(0, 300)); });
  page.on('pageerror', (e) => consoleErrors.push(`pageerror: ${String(e).slice(0, 300)}`));
  page.on('requestfailed', (r) => failedRequests.push(`${r.url()} ${r.failure()?.errorText ?? ''}`.slice(0, 300)));
  const responses = [];
  page.on('response', (r) => responses.push(`${r.status()} ${r.url()}`));
  await page.goto(server.origin, { waitUntil: 'networkidle', timeout: 20000 });
  const shell = await page.evaluate(() => ({
    title: document.title,
    baseHref: document.querySelector('base')?.getAttribute('href') ?? null,
    baseResolved: document.baseURI,
    appRootPresent: document.querySelector('app-pi-gallery2') !== null,
    appRootChildElementCount: document.querySelector('app-pi-gallery2')?.childElementCount ?? -1,
    visibleText: (document.body.innerText || '').trim().slice(0, 200),
    scriptSrcs: [...document.querySelectorAll('script[src]')].map((s) => s.getAttribute('src')),
    scriptsResolved: [...document.querySelectorAll('script[src]')].map((s) => s.src),
    serverInjectDefined: typeof globalThis.ServerInject !== 'undefined',
    scrollHeight: document.documentElement.scrollHeight,
    clientHeight: document.documentElement.clientHeight,
  }));
  out[lane] = {
    laneRoot: root,
    crawl: {
      routesDeclared: reading.journeys[0]?.steps?.length ?? null,
      journeyCount: reading.journeys.length,
      visited: reading.visited.map((v) => ({ route: v.route, depth: v.depth, status: v.status, contentType: v.contentType })),
      routesFromJourney: reading.journeys.map((j) => j.steps.map((s) => s.route ?? s.selector ?? s.kind)),
      consideredOrigins: reading.locality.consideredOrigins,
      refusedNonLoopbackOrigins: reading.locality.refusedNonLoopbackOrigins,
      requestsIssued: reading.locality.requestsIssued,
      nonLoopbackRequests: reading.locality.nonLoopbackRequests,
      refusedReason: reading.refusedReason,
    },
    shell,
    consoleErrors,
    failedRequests,
    responses,
  };
  await browser.close();
  await server.close();
}
console.log(JSON.stringify(out, null, 1));
